		klasse: k.klasse,
		retrybar: k.retrybar,
		eskalieren: k.eskalieren && Boolean(k.vorgangsId) && !ausSicherung,
		workflow_id: workflow.id || null,
		workflow_name: workflow.name || null,
		node,
